"use client";

import { useQuery } from "convex/react";
import { api } from "@convex/api";

export default function UsersPage() {
  const users = useQuery(api.admin.listUsers);

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Users</h1>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Ecosystem</th>
              <th>Tier</th>
              <th>Fraud Score</th>
              <th>Country</th>
            </tr>
          </thead>
          <tbody>
            {users?.map((u) => (
              <tr key={u._id}>
                <td>{u.username}</td>
                <td><span className={`badge ${u.ecosystem === "PI" ? "badge-green" : "badge-yellow"}`}>{u.ecosystem}</span></td>
                <td>{u.tier}</td>
                <td>{u.fraudScore}</td>
                <td>{u.country}</td>
              </tr>
            ))}
            {users?.length === 0 && (
              <tr><td colSpan={5} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>No users yet</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
